import{PRICES,CHANNELS,parseCSV,rowsAt,blend,validMix}from'./model.js';
const $=id=>document.getElementById(id),eur=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(n),pct=n=>Number(n).toFixed(1)+'%',escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let price=2.19,weights=[40,40,20],data;
const files=['price_test_results','channel_economics','cost_breakdown','competitor_prices_by_channel','market_context'];
async function start(){data=Object.fromEntries(await Promise.all(files.map(async name=>{const response=await fetch('/data/'+name+'.csv');if(!response.ok)throw Error('Cannot load '+name);return[name,parseCSV(await response.text())];})));for(const p of PRICES)for(const r of rowsAt(data.price_test_results,p)){for(const key of ['estimated_acceptance_pct_of_survey','net_price_to_lumen_eur','unit_contribution_eur'])if(!r[key]||!Number.isFinite(Number(r[key])))throw Error('Invalid numeric price-test data');}
$('prices').innerHTML=PRICES.map(p=>`<button data-price="${p}" aria-label="Launch price ${eur(p)}">${eur(p)}</button>`).join('');$('weights').innerHTML=CHANNELS.map((c,i)=>`<div class="weight"><label for="w${i}">${c}</label><span><input id="w${i}" aria-label="${c} share of units sold, percent" type="number" min="0" max="100" step="1" value="${weights[i]}"> %</span></div>`).join('');$('chartChannel').innerHTML=CHANNELS.map(c=>`<option>${c}</option>`).join('');document.addEventListener('click',e=>{const b=e.target.closest('[data-price]');if(b){price=Number(b.dataset.price);render();}});CHANNELS.forEach((c,i)=>$('w'+i).addEventListener('input',e=>{weights[i]=e.target.value===''?NaN:Number(e.target.value);$('preset').value='mix';render();}));$('preset').addEventListener('change',e=>{if(e.target.value==='mix')return;weights=CHANNELS.map(c=>c===e.target.value?100:0);weights.forEach((w,i)=>$('w'+i).value=w);render();});$('priority').addEventListener('change',render);$('chartChannel').addEventListener('change',chart);
const market=data.market_context.filter(r=>r.dimension_type==='subcategory'&&r.metric==='market_size_eur'&&r.year==='2026');$('context').innerHTML='<p class="eyebrow">GERMAN MARKET CONTEXT · 2026</p><div class="contextgrid">'+market.map(r=>`<div>${escape(r.name)}<strong>€${(Number(r.value)/1e9).toFixed(2)}bn</strong></div>`).join('')+'</div><p class="small">Supplied category market estimates, not forecast LUMEN revenue. Source: market_context.csv.</p>';$('sources').innerHTML='<p>'+files.map(f=>`<a href="/data/${f}.csv">${f}.csv</a>`).join(' · ')+'</p>';render();}
function render(){const rows=rowsAt(data.price_test_results,price),mixed=blend(data.price_test_results,price,weights),valid=validMix(weights);document.querySelectorAll('#prices button').forEach(b=>{b.classList.toggle('active',Number(b.dataset.price)===price);b.setAttribute('aria-pressed',Number(b.dataset.price)===price);});$('total').textContent=valid?'100% allocated':`Mix total: ${weights.every(Number.isFinite)?weights.reduce((a,b)=>a+b,0)+'%':'incomplete'} — enter 0–100% per channel and total 100%.`;$('total').className=valid?'small':'small invalid';$('summary').innerHTML='<div class="metrics">'+[['Launch price',eur(price),'Per can · all selected channels'],['Blended contribution / can',mixed?eur(mixed.contribution):'—','After channel cuts and unit cost'],['Contribution margin',mixed?pct(mixed.percent):'—','Share of LUMEN net revenue']].map(([label,value,note])=>`<div class="metric"><span>${label}</span><strong>${value}</strong><span>${note}</span></div>`).join('')+'</div>';$('channels').innerHTML=rows.map((r,i)=>`<tr class="${weights[i]===0?'muted':''}"><td>${r.channel}</td><td>${Number.isFinite(weights[i])?weights[i]+'%':'—'}</td><td>${pct(r.estimated_acceptance_pct_of_survey)}</td><td>${eur(r.net_price_to_lumen_eur)}</td><td>${eur(r.unit_contribution_eur)}</td></tr>`).join('');$('compare').innerHTML=PRICES.map(p=>{const b=blend(data.price_test_results,p,weights),rs=rowsAt(data.price_test_results,p);return`<div class="option ${p===price?'active':''}"><button data-price="${p}" aria-label="Select launch price ${eur(p)}" aria-pressed="${p===price}">${eur(p)}</button><p>Contribution / can <b>${b?eur(b.contribution):'—'}</b></p>${rs.map(r=>`<p>${r.channel}<br><b>${pct(r.estimated_acceptance_pct_of_survey)}</b> tested acceptance</p>`).join('')}</div>`;}).join('');
const priority=$('priority').value;let advice='Choose a priority to see a conditional recommendation. Higher prices improve unit contribution in this test, while acceptance falls. Your sales mix changes the contribution you retain.';if(priority&&valid){const candidates=PRICES.map(p=>({p,b:blend(data.price_test_results,p,weights),rs:rowsAt(data.price_test_results,p)}));const score=c=>priority==='contribution'?c.b.contribution:Math.min(...c.rs.filter((r,i)=>weights[i]>0).map(r=>Number(r.estimated_acceptance_pct_of_survey)));candidates.sort((a,b)=>score(b)-score(a));const win=candidates[0],other=candidates[candidates.length-1];advice=`For ${priority==='contribution'?'highest contribution per unit':'highest tested acceptance'}, prefer ${eur(win.p)} under your chosen mix: ${eur(win.b.contribution)} contribution per can. ${win.rs.filter((r,i)=>weights[i]>0).map(r=>r.channel+': '+pct(r.estimated_acceptance_pct_of_survey)+' acceptance').join('; ')}. Compared with ${eur(other.p)}, this ${priority==='contribution'?'sacrifices acceptance for margin':'sacrifices margin for acceptance'}.`;}else if(!valid)advice='Complete a valid 100% channel mix to compare blended contribution and receive a recommendation.';$('advice').innerHTML=`<p>${escape(advice)}</p><p>A sales mix is your assumption, not a recommended allocation. Actual demand and channel capacity are needed to recommend launch volumes. Payback cannot be established from unit margins alone.</p>`;chart();}
function chart(){const channel=$('chartChannel').value;const competitors=['PulsUp','Mate Libre','VoltFit','Root & Rise'];const points=competitors.map(name=>({name,row:data.competitor_prices_by_channel.find(r=>r.competitor===name&&r.channel===channel&&r.format==='Single can (330ml)')}));$('chart').innerHTML=points.map(({name,row})=>chartRow(name,row?Number(row.price_eur):null)).join('')+chartRow('LUMEN',price,true)+'<div class="chartrow"><span>Price / 330 ml can</span><div class="axis"><span>€0</span><span>€1.75</span><span>€3.50</span></div><span></span></div>';}
function chartRow(name,value,lumen=false){return`<div class="chartrow ${lumen?'lumen':''}"><span>${name}</span><div class="track">${value===null?'':`<span class="dot" style="left:${value/3.5*100}%"></span>`}</div><span>${value===null?'Not listed':eur(value)}</span></div>`;}
start().catch(e=>{$('error').textContent='Unable to load the case data. '+e.message+'. Run the local server from the repository folder and reload.';});
